sql.where:
l.tenant_id = #{q.tenantId}

    AND l.login_result = #{q.loginResult}


    AND l.event_id = #{q.eventId}


    AND l.host_id = #{q.hostId}


    AND l.login_type = #{q.loginType}


    AND l.username LIKE CONCAT('%', #{q.username}, '%')


    AND l.source_ip LIKE CONCAT('%', #{q.sourceIp}, '%')


    AND (l.username LIKE CONCAT('%', #{q.keyword}, '%')
         OR l.source_ip LIKE CONCAT('%', #{q.keyword}, '%')
         OR l.process_name LIKE CONCAT('%', #{q.keyword}, '%'))


    AND l.event_time >= #{q.startTime}


    AND l.event_time <= #{q.endTime}

mapper.select:
SELECT COUNT(1)
FROM login_security_logs
WHERE login_result = #{result}
  AND tenant_id = #{tenantId}
  AND DATE(event_time) = CURDATE()
